def maximised_height(arr, n, m):
	lo = min(arr)
	hi = max(arr) + m
	ans = -1
	while lo <= hi:
		mi = (lo + hi) // 2
		if ok(arr, n, mi, m):
			ans = mi
			lo = mi + 1
		else:
			hi = mi - 1
	return ans

def ok(a, n, mi, m):
	ans = 0
	for i in range(n):
		if a[i] < mi:
			ans += mi - a[i]
	return ans <= m
